def choose_move(observation):
    # Defensive defaults
    # Observe possible directions: up, down, left, right, stay
    dx = 0
    dy = 0

    # Safely extract common fields
    # Prefer not to assume structure; fall back to defaults if missing
    pos = observation.get("position", {})
    x = pos.get("x", 0)
    y = pos.get("y", 0)

    # Look for resources, enemies, or territory cues with safe access
    grid = observation.get("grid", [])
    height = len(grid)
    width = len(grid[0]) if height > 0 else 0

    # Helper to check cell content safely
    def cell_at(nx, ny):
        if 0 <= ny < height and 0 <= nx < width:
            row = grid[ny]
            if isinstance(row, list) and len(row) > nx:
                return row[nx]
        return None

    # Priority: avoid danger, move toward useful cues if present
    # 1) If an enemy nearby, try to move away
    for dyi in (-1, 0, 1):
        for dxi in (-1, 0, 1):
            if abs(dxi) + abs(dyi) != 1:
                continue
            nx, ny = x + dxi, y + dyi
            cell = cell_at(nx, ny)
            if isinstance(cell, dict):
                if cell.get("type") == "enemy":
                    # Move away from enemy if possible
                    if dxi != 0:
                        dx = -dxi
                    elif dyi != 0:
                        dy = -dyi
                    # break once a threatening neighbor found
                    break

    # 2) If resource present nearby, move toward it
    if dx == 0 and dy == 0:
        for dyi in (-1, 0, 1):
            for dxi in (-1, 0, 1):
                if abs(dxi) + abs(dyi) != 1:
                    continue
                nx, ny = x + dxi, y + dyi
                cell = cell_at(nx, ny)
                if isinstance(cell, dict) and cell.get("type") == "resource":
                    dx, dy = dxi, dyi
                    break
            if dx != 0 or dy != 0:
                break

    # 3) If territory control data exists, bias toward own controlled cells
    if dx == 0 and dy == 0:
        for dyi in (-1, 0, 1):
            for dxi in (-1, 0, 1):
                if abs(dxi) + abs(dyi) != 1:
                    continue
                nx, ny = x + dxi, y + dyi
                cell = cell_at(nx, ny)
                if isinstance(cell, dict) and cell.get("type") == "territory":
                    owner = cell.get("owner")
                    if owner == observation.get("player_id"):
                        dx, dy = dxi, dyi
                        break
            if dx != 0 or dy != 0:
                break

    # 4) If no cues, try a neutral move (stay or random-like in deterministic way)
    if dx == 0 and dy == 0:
        # Deterministic: prefer to move right, then down, then left, then up
        for cand in [(1,0),(0,1),(-1,0),(0,-1),(0,0)]:
            nx, ny = x + cand[0], y + cand[1]
            cell = cell_at(nx, ny)
            # avoid obvious walls if possible
            if cell is None or cell == {}:
                dx, dy = cand
                break
        else:
            dx, dy = 0, 0

    # Ensure final values are within -1..1
    if dx not in (-1, 0, 1):
        dx = 0
    if dy not in (-1, 0, 1):
        dy = 0

    return [dx, dy]

